def uvfill(lanes, markers):
 # lane tuple (v, start_u,end_u)
 out=set()
 lanes=sorted(lanes)
 for (v1,u1a,u1b),(v2,u2a,u2b) in zip(lanes,lanes[1:]):
  lo=max(u1a,u2a); hi=min(u1b,u2b)
  if lo>hi: continue
  for r in range(16):
   for c in range(16):
    u=r+c;v=c-r
    if lo<=u<=hi and v1<v<v2 and (r,c) not in markers:
     out.add((r,c))
 return out
