def get_v_segments(markers):
 byv=defaultdict(list)
 for r,c in markers: byv[c-r].append(r+c)
 segs=[]
 for v,us in byv.items():
  us=sorted(us); chunks=[]
  for u in us:
   if not chunks or u>chunks[-1][-1]+2: chunks.append([u])
   else: chunks[-1].append(u)
  for ch in chunks: segs.append((v,ch[0],ch[-1]))
 return sorted(segs)
