def uvfill_from_segments(markers):
 segs=get_v_segments(markers)
 out=set()
 for i,(v1,u1a,u1b) in enumerate(segs):
  for v2,u2a,u2b in segs[i+1:]:
   if v2<=v1: continue
   # Only adjacent v tracks, accounting for separate segments with same v as contiguous track? Pair nearest higher distinct v
   nxt=min(s[0] for s in segs if s[0]>v1)
   if v2 != nxt: continue
   lo=max(u1a,u2a); hi=min(u1b,u2b)
   if lo>hi: continue
   for r in range(16):
    for c in range(16):
     u=r+c;v=c-r
     if lo<=u<=hi and v1<v<v2 and (r,c) not in markers: out.add((r,c))
 return out
